def _to_code_units(s: str):
    raw = s.encode('utf-16-le', errors='surrogatepass')
    return struct.unpack(f'<{len(raw) // 2}H', raw)

def _f32(val: float) -> float:
    return struct.unpack('>f', struct.pack('>f', float(val)))[0]

class JaroWinkler:
    DEFAULT_THRESHOLD = 0.7
    THREE = 3
    JW_COEF = 0.1

    def __init__(self, threshold=DEFAULT_THRESHOLD):
        self.threshold = threshold

    def get_threshold(self):
        return self.threshold

    def similarity(self, s1, s2):
        if s1 is None:
            raise ValueError('s1 must not be null')
        if s2 is None:
            raise ValueError('s2 must not be null')
        if s1 == s2:
            return 1.0

        u1 = _to_code_units(s1)
        u2 = _to_code_units(s2)
        mtp = self._matches(u1, u2)
        m = _f32(mtp[0])
        if m == 0.0:
            return 0.0

